mapper.select:
select t.outbound_order, t.primary_key outboundOrderDetailCode, t1.contract_number, t1.outbound_type, p.product_part_sign, p.primary_key productPartCode, p.model, s.bar_code_number, s.shipping_space::BIGINT[], t.out_total, t.accrual_out_total, t.accrual_lock_in_inventory, s.total_inventory, s.lock_in_inventor, t.await_num, t.out_num, p.pcs, t.outbound_status, t.apply_details::BIGINT[], t.outbound_staff::BIGINT[], t1.business_code, t1.remark, t1.batch_num, s.stock_init_state, s.primary_key stock from ${outboundOrderDetailTableName} t left join ${productPartTableName} p on t.product_or_part = p.primary_key left join ${stockTableName} s on t.product_or_part = s.product_part_code left join ${outboundOrderTableName} t1 on t.outbound_order = t1.primary_key where t.enterprise_code = #{enterpriseCode} and t.delete_flag = false
and ${dynamicTableNameProxy.getXiHangPartQuery("t.product_or_part","xihang",requestData.partUnityNo)}
AND t1.contract_number like '%'|| #{requestData.contractNumber} ||'%'
AND t.outbound_staff && ARRAY[
#{item}
]::bigint[]
AND p.product_part_sign like '%'|| #{requestData.productOrPartName} ||'%'
AND p.model like '%'|| #{requestData.model} ||'%'
AND (p.model like '%'|| #{requestData.searchName} ||'%' or p.product_part_sign like '%'|| #{requestData.searchName} ||'%')
AND t.outbound_status IN
#{item}
AND t1.outbound_type IN
#{item}
${dataScopeParams.dataScope}
order by t.create_time desc,t.id desc

select t.outbound_order, t.primary_key outboundOrderDetailCode, t1.contract_number, t1.outbound_type, p.product_part_sign, p.primary_key productPartCode, p.model, s.bar_code_number, s.shipping_space::BIGINT[], t.out_total, t.accrual_out_total, t.accrual_lock_in_inventory, s.total_inventory, s.lock_in_inventor, t.await_num, t.out_num, p.pcs, t.outbound_status, t.apply_details::BIGINT[], t.outbound_staff::BIGINT[], t1.business_code, t1.remark, t1.batch_num, s.stock_init_state, s.primary_key stock from ${outboundOrderDetailTableName} t left join ${productPartTableName} p on t.product_or_part = p.primary_key left join ${stockTableName} s on t.product_or_part = s.product_part_code left join ${outboundOrderTableName} t1 on t.outbound_order = t1.primary_key where t.enterprise_code = #{enterpriseCode} and t.delete_flag = false and ( t1.outbound_type != #{typeCode} OR (t1.outbound_type = #{typeCode} AND t.accrual_out_total > 0) )
and ${dynamicTableNameProxy.getXiHangPartQuery("t.product_or_part","xihang",requestData.partUnityNo)}
AND t1.contract_number like '%'|| #{requestData.contractNumber} ||'%'
AND t.outbound_staff && ARRAY[
#{item}
]::bigint[]
AND p.product_part_sign like '%'|| #{requestData.productOrPartName} ||'%'
AND p.model like '%'|| #{requestData.model} ||'%'
AND (p.model like '%'|| #{requestData.searchName} ||'%' or p.product_part_sign like '%'|| #{requestData.searchName} ||'%')
AND t.outbound_status IN
#{item}
AND t1.outbound_type IN
#{item}
${dataScopeParams.dataScope}
order by t.create_time desc,t.id desc

