mapper.select:
select t.primary_key, t.out_total, t.await_num, t.out_num, t.outbound_status, t.apply_details::BIGINT[], t.product_or_part as productPartCode, t.accrual_out_total, t.outbound_staff, t.accrual_lock_in_inventory, t1.contract_number, t1.business_code, t1.outbound_type, t2.total_inventory - COALESCE(t2.lock_in_inventor,0) + COALESCE(t.accrual_lock_in_inventory,0) as totalInventory from ${outboundOrderTableName} t1 left join ${outboundOrderDetailTableName} t on t1.primary_key = t.outbound_order left join ${stockTableName} t2 on t2.primary_key = t.stcok where t1.enterprise_code = #{enterpriseCode}
and t1.contract_number IN
#{item}
and t.product_or_part IN
#{item}
and t1.delete_flag = 'f'

select t1.primary_key, t1.outbound_quantity as outNum, t1.collaborate_material as productPartCode, t1.contract_number, t2.total_inventory - COALESCE(t2.lock_in_inventor,0) + COALESCE(t1.accrual_lock_in_inventory,0) as totalInventory, t1.accrual_lock_in_inventory, t1.outbound_quantity as out_num, t1.schedule_quantity from ${collaborateScheduleItemTableName} t1 left join ${positionOperationTableName} t on t1.primary_key = t.detail_code left join ${stockTableName} t2 on t2.product_part_code = t1.collaborate_material where t1.enterprise_code = #{enterpriseCode} and t1.collaborate_type = 0
and t1.contract_number IN
#{item}
and t1.collaborate_material IN
#{item}
and t1.delete_flag = 'f'

select a.outbound_Type,
a.contract_Number,
a.outbound_Status,
a.business_Code,
a.primary_key order_Id,
b.primary_key detail_Id,
b.product_Or_Part,
c.primary_key apply_Id,
c.batch_Global_Code,
c.stock_Type,
c.produce_Bubble
from ${dynamicTableNameProxy.outboundOrder} a,
${dynamicTableNameProxy.outboundOrderDetail} b,
${dynamicTableNameProxy.outboundApplyDetail} c
where a.primary_key = b.outbound_order
and c.primary_key = any (b.apply_details)

and a.delete_flag = false
and a.enterprise_code = ${dynamicTableNameProxy.enterpriseCode}
and b.enterprise_code = ${dynamicTableNameProxy.enterpriseCode}
and c.enterprise_code = ${dynamicTableNameProxy.enterpriseCode}
and b.delete_flag = false
and c.delete_flag = false


    and c.batch_global_code = #{data.batchGlobalCode}



    and a.outbound_Type = #{data.outboundType}



    and a.contract_number = #{data.contractNumber}




    and a.primary_key = #{data.orderId}

SELECT pp.unity_no, pp.product_part_sign, pp.model, SUM(COALESCE(ood.accrual_out_total, 0)) AS accrual_out_total, SUM(COALESCE(ood.out_num, 0)) AS out_num, SUM(COALESCE(ood.accrual_out_total, 0)) - SUM(COALESCE(ood.out_num, 0)) AS difference FROM ${outboundOrderDetailTableName} ood LEFT JOIN ${productPartTableName} pp ON ood.product_or_part = pp.primary_key WHERE ood.outbound_status != #{state} and ood.enterprise_code = #{enterpriseCode} and ood.delete_flag = false
AND ood.create_time >= #{requestData.startTime}
AND ood.create_time <= #{requestData.endTime}
GROUP BY pp.unity_no, pp.product_part_sign, pp.model order by difference desc

SELECT primary_key
FROM ${tableName}
WHERE delete_flag = false
  AND enterprise_code = #{enterpriseCode}
  AND contract_number = #{contractNumber}
  AND (outbound_type = 323909030715064320)
ORDER BY create_time DESC
